UPDATE companies SET description='The John R. White Company, Inc. is headquartered in Birmingham, Alabama. The business was established in 1947 by John R. White and L.Q. Patton as a specialized supplier of dairy and bakery ingredients. Over the decades it has evolved into a value‑added distributor of bulk dry ingredients with a focus on functional and technical products.

Today the company operates as a value‑add ingredient distributor, offering strategic sourcing, technical consultation, and reliable execution. It represents more than 100 bulk dry ingredient manufacturers and serves over 800 active customers from BRC‑certified facilities, distributing to more than 38 states primarily in the South. Services include formulation support, ingredient optimization, supply chain management, and inventory optimization.

The company serves food manufacturers across categories such as dry blending and milling, meat and poultry, bakery and snack, beverage and premix, pet food, clean label, spices, and dressings, soups and sauces. Its customer base includes procurement and buying teams, business owners and operations leaders, and R&D and technical staff who rely on the firm for ingredient sourcing, cost reduction, and formulation troubleshooting.

Founded on principles of reliability and cost‑competitiveness, the company differentiates itself through a technical sales force that works directly with client R&D and production teams, a total‑cost sourcing methodology, and a four‑pillar philosophy of innovative solutions, exceptional customer service, earning trust, and building community. A strategic partnership with Bunge to scale soy protein solutions further extends its ingredient portfolio.', certifications=ARRAY['BRC','BRC AA Rating']::text[], profile='{"capabilities": ["Strategic Sourcing", "Technical Services", "Formulation Support", "Ingredient Optimization", "Supply Chain Management", "Inventory Optimization", "Distribution", "Yield Improvement", "Ingredient Consolidation", "Supply Stability", "Reformulation Support", "Cost Optimization", "Process Improvement"], "industries": ["Dry Blending & Milling", "Meat & Poultry", "Bakery & Snack", "Beverage & Premix", "Pet Food", "Clean Label", "Spices", "Dressing, Soup & Sauces"], "materials": ["Bulk dry ingredients", "Functional ingredients", "Technical ingredients", "Dairy ingredients", "Bakery ingredients", "Soy protein"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Technical team works directly with R&D and production staff", "Strategic sourcing evaluates ingredient performance against total cost", "BRC-certified operations ensure on-time, in-spec delivery", "Represents over 100 bulk dry ingredient manufacturers", "Distribution to more than 38 states"], "facts_used": ["Headquartered in Birmingham, Alabama -> db", "Founded in 1947 by John R. White and L.Q. Patton -> /about", "Started as specialized supplier of dairy and bakery ingredients -> /about", "Value-add ingredient distributor -> /", "Represents over 100 bulk dry ingredient manufacturers -> /about", "Serves over 800 active customers -> /about", "BRC-certified operations -> /, /about", "Distributes to more than 38 states -> /about", "Offers strategic sourcing, technical services, reliable execution -> /", "Services: formulation support, ingredient optimization, supply chain management, inventory optimization -> /, /about", "Industries served: dry blending & milling, meat & poultry, bakery & snack, beverage & premix, pet food, clean label, spices, dressing/soup/sauces -> /", "Customer types: procurement/buyers, business owners/operations, R&D/technical teams -> /", "Four pillars: innovative solutions, exceptional customer service, earning trust, building community -> /about", "Strategic partnership with Bunge for soy protein solutions -> /", "Certifications: BRC, BRC AA Rating -> db, /"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "John R. White is a value-add ingredient distributor.", "founded_year": "1947", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='the-john-r-white-company-inc' AND approved AND profile IS NULL;
