UPDATE companies SET description='The Regrainery is a custom furniture shop based in southeast Portland, Oregon, founded in 2016. The business began in a small garage and has grown while maintaining a deliberately small scale, focusing on hand-built pieces for homes and offices.

The shop specializes in custom hardwood dining tables but also produces benches, desks, cabinetry, and a small line of ready-made products. A team of woodworkers with backgrounds ranging from guitar-making to architecture collaborates on each project, handling design, build, and installation. The company intentionally limits its workload so that booked clients receive full attention until completion.

Clients include homeowners and small businesses seeking one-off furniture for residential and office spaces.

The Regrainery was started out of a love for the craft of woodworking and a desire to blend high-quality construction with exceptional service. The founders emphasize a highly collaborative process—both within the team and with clients—and a commitment to delivering finished pieces on schedule.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom woodworking", "Hand-built furniture fabrication", "Custom hardwood dining tables", "Bench building", "Desk building", "Cabinetry", "Custom one-off pieces", "Design collaboration", "Build and installation", "Small product line"], "industries": ["Residential furniture", "Office furniture", "Home furnishings", "Custom millwork"], "materials": ["Hardwood", "Walnut"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Commits to fewer projects at a time so booked clients have the team''s full focus", "Builds furniture by hand while intentionally keeping the shop''s scale small", "Runs a highly collaborative design process involving both the team and the client", "Blends high-quality woodworking with exceptional service and on-time delivery", "Started from a garage out of a love for the craft of woodworking"], "facts_used": ["Founded 2016 -> db, /, /about", "Headquarters southeast Portland, Oregon -> db, /about", "Custom hand-built furniture company -> /, /about", "Specializes in custom hardwood dining tables -> /", "Also builds benches, desks, cabinetry -> /about", "Small team of woodworkers from diverse backgrounds -> /about", "Collaborative design process -> /about", "Commits to fewer projects for client focus -> /", "On hiatus July 2026 to 2027 -> /, /about", "Client testimonials for dining tables, vanities, banquettes, cabinets, cutting boards, bookcases, wardrobes, room dividers -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "The Regrainery is a custom hand-built furniture company based in Portland, Oregon.", "founded_year": "2016", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='the-regrainery-custom-woodworking-hand-built-furniture-in-portland-or' AND approved AND profile IS NULL;
UPDATE companies SET description='The Solar Guys was founded in 2014 in Ankeny, Iowa, by brothers Jesse and Jereme.

The company designs and installs custom solar energy systems for residential and commercial properties, along with battery backup and service for existing arrays. All work is performed in-house — from site assessment and system engineering through permitting, installation, and ongoing monitoring — without subcontractors. They evaluate roof condition, structure energy-use data, and size each system to the property’s long-term performance. A 25-year workmanship warranty covers every installation.

The Solar Guys serves homeowners and commercial property owners in Kansas, Missouri, and Iowa. Residential clients receive custom rooftop systems sized to actual usage, while commercial projects are engineered for 10-, 20-, and 25-year returns, with assistance navigating tax credits, depreciation, and C-PACE financing. The team also services and repairs systems it did not originally install.

The brothers started the business to offer honest pricing, real-person communication, and installations built to outlast the warranty. Their differentiators include a fully in-house crew, no-subcontractor policy, custom design for every roof and budget, and a commitment to handle all permitting and utility paperwork.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Residential solar system design and installation", "Commercial solar system design and installation", "Solar system service and repair", "Battery backup system design and installation", "Custom system design based on energy usage analysis", "In-house installation (no subcontractors)", "Permitting and utility interconnection management", "Financing and incentive structuring (ITC, depreciation, C-PACE)", "Roof condition evaluation", "System performance monitoring", "25-year workmanship warranty"], "industries": ["Residential", "Commercial", "Solar energy"], "materials": [], "equipment": [], "volume": "", "lead_time": "1-2 days for residential installation after permitting", "tolerances": "", "built_on": ["In-house design, installation, and support with no subcontractors", "Custom-designed systems for each property\u2019s energy use and roof", "25-year workmanship warranty on all installations", "Service and repair for systems installed by other providers", "Full permitting and utility interconnection management"], "facts_used": ["Founded 2014 -> db", "Headquarters Ankeny, Iowa -> db", "Brother-owned (Jesse & Jereme) -> /", "Service area Kansas, Missouri, Iowa -> /", "In-house design, installation, support, no subcontractors -> /", "Residential, commercial, battery backup, service offerings -> /", "25-year workmanship warranty -> /", "Custom system design per property -> /", "Permitting and utility paperwork handled -> /", "Financing assistance with ITC, depreciation, C-PACE -> /", "Service systems not originally installed -> /", "Residential install 1-2 days after permitting -> /"], "company_ty